import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { SLICE_1A } from './mutation-tree/src/content/slice-1a.ts';
import { BUILD, TREE } from './mutation-tree/src/content/rules.ts';
import { groundLanes } from './mutation-tree/src/sim/lanes.ts';
import { canPlace } from './mutation-tree/src/sim/placement.ts';
import { world, built, def } from './mutation-tree/tests/td/fixtures.ts';
import { roadField } from './mutation-tree/src/view/3d/road.ts';
import { heightAt } from './mutation-tree/src/view/3d/ground.ts';
import { sceneryLayout, buildableAt, type SceneryInput, type SceneryItem } from './mutation-tree/src/view/3d/scenery-layout.ts';

// Phiếu 231: oracle độc lập. Không import/copy inspectLayout, FOOT, T hoặc helper placement của 202.
const map = SLICE_1A.map, lanes = groundLanes(map.routes);
const roads = roadField(map, lanes, 88);
const houses = (map.preset ?? []).map(([id,x,z]) => ({x,z,r:BUILD.footprintR[SLICE_1A.buildings.find(b=>b.id===id)!.footprint]}));
const base = {map, houses, roadHalf:roads.widths, dressing: roads.dressing.map(d=>({x:d.x,z:d.z,r:(d.kind==='stones'?1:3)*d.scale})), heightAt:(x:number,z:number)=>heightAt(map,x,z)};
const real = JSON.parse(readFileSync(new URL('./mutation-tree/scripts/td/scenery-set.json',import.meta.url),'utf8'));
const sampleSpec = [
 ['almond-tree','tree',18,14],['mountain-pine','tree',14,10],['bamboo-clump','bamboo',16,16],['canopy-block','canopy',10,14],
 ['fern','bush',2.3,1.5],['reed-clump','grass',3,2.2],['tall-grass','grass',2.5,1.7],['wildflowers','flower',1,.8],
 ['raspberry-bush','bush',1.8,1.2],['rock-medium','rock',3.4,2.561141],['rock-small','rock',.664719,.594675],
 ['rotten-log','log',2.368047,2.462413],['tree-stump','stump',2.3,1.465127],
] as const;
const sample=sampleSpec.flatMap(([type,kind,a,b])=>[a,b].map((heightM,k)=>({id:`${type}-v${k+3}`,type,kind,variant:`v${k+3}`,heightM})));
const tiers=['low','medium','high'] as const;
const seeds=[undefined,...Array.from({length:20},(_,i)=>i+1),20261030];
const sha=(s:string)=>createHash('sha256').update(s).digest('hex');
function fnvItems(items:SceneryItem[]) {
 let h=2166136261;
 const s=JSON.stringify(items.map(p=>({...p,x:Math.round(p.x*100)/100,z:Math.round(p.z*100)/100,r:Math.round(p.r*100)/100,scale:Math.round(p.scale*1000)/1000,tint:Math.round(p.tint*1000)/1000,shade:Math.round(p.shade*1000)/1000})));
 for(let n=0;n<s.length;n++)h=Math.imul(h^s.charCodeAt(n),16777619)>>>0;
 return h.toString(16).padStart(8,'0');
}
const golden=Object.fromEntries([undefined,1,20261030].map(seed=>[seed??'default',Object.fromEntries(tiers.map(tier=>[tier,fnvItems(sceneryLayout({...base,set:sample,seed},tier).items)]))]));
const fullByteHashes=Object.fromEntries([undefined,1,20261030].map(seed=>[seed??'default',Object.fromEntries(tiers.map(tier=>[tier,sha(JSON.stringify(sceneryLayout({...base,set:sample,seed},tier)))]))]));
if(process.argv.includes('--hashes-only')) {process.stdout.write(JSON.stringify({golden,fullByteHashes}));process.exit(0);}

const square=(v:number)=>v*v;
const dist=(a:{x:number,z:number},b:{x:number,z:number})=>Math.hypot(a.x-b.x,a.z-b.z);
const rectGap=(q:any,x:number,z:number)=>Math.hypot(Math.max(q.x0-x,0,x-q.x1),Math.max(q.z0-z,0,z-q.z1));
const contains=(q:any,x:number,z:number)=>q.x0<=x&&x<=q.x1&&q.z0<=z&&z<=q.z1;
const water=map.water.map(q=>({x0:q.x0<=-48?-88:q.x0,x1:q.x1>=48?88:q.x1,z0:q.z0<=-48?-88:q.z0,z1:q.z1>=48?88:q.z1}));
const segments=lanes.flatMap((lane,l)=>Array.from({length:lane.xs.length-1},(_,k)=>({ax:lane.xs[k]!,az:lane.zs[k]!,bx:lane.xs[k+1]!,bz:lane.zs[k+1]!,w0:roads.widths[l]![k]!,w1:roads.widths[l]![k+1]!})));
function roadMetrics(p:{x:number,z:number,r:number}) {
 let clearance=Infinity,centre=Infinity;
 for(const s of segments) {
  const vx=s.bx-s.ax,vz=s.bz-s.az;
  const u=Math.max(0,Math.min(1,((p.x-s.ax)*vx+(p.z-s.az)*vz)/(vx*vx+vz*vz)));
  const d=Math.hypot(p.x-s.ax-u*vx,p.z-s.az-u*vz);
  centre=Math.min(centre,d);
  clearance=Math.min(clearance,d-(s.w0+(s.w1-s.w0)*u)-.8-p.r);
 }
 return {clearance,centre};
}
function pointBuildable(x:number,z:number) {
 if(Math.abs(x)>46||Math.abs(z)>46)return false;
 if([...map.water,...map.bridges].some(q=>contains(q,x,z)))return false;
 if(Math.hypot(x-map.keep[0],z-map.keep[1])<11)return false;
 if(houses.some(h=>Math.hypot(h.x-x,h.z-z)<h.r+1))return false;
 if(map.trees.some(([tx,tz])=>Math.hypot(tx-x,tz-z)<1.5))return false;
 // Terrain point rules use sampled sim centreline, independently measured here.
 return !lanes.some(l=>l.xs.some((tx,k)=>square(tx-x)+square(l.zs[k]!-z)<square(1.9)));
}
const w=world();for(const [id,x,z] of map.preset??[])built(w,id,x,z);
const archer=def(w,'archer');
const cells:any[]=[];let exportedBuildabilityDisagreements=0;
for(let x=-46;x<=46;x++)for(let z=-46;z<=46;z++) {
 const ok=canPlace(w,archer,x/BUILD.snapM,z/BUILD.snapM,true).ok;
 cells.push({x,z,ok});
 if(pointBuildable(x,z)!==buildableAt({...base,set:sample},x,z))exportedBuildabilityDisagreements++;
}
console.log('tower grid',cells.length,'legal',cells.filter(p=>p.ok).length);

function inspect(items:SceneryItem[],set:any[]) {
 const violations:Record<string,number>={road:0,dressing:0,bridge:0,keepYard:0,house:0,ore:0,ruleTreeFoot:0,water:0,bounds:0,keepLarge:0,gateLarge:0,slope4:0,slope64Diagnostic:0,fixedBuildableFoot:0,fixedBuildableProbe:0,fieldFixed:0,sameNearestVariant:0,scale:0,tint:0,forestZone:0,forestShade:0};
 const minima:Record<string,number>={roadFootClearM:Infinity,dressingFootClearM:Infinity,bridgeFootClearM:Infinity,keepYardFootClearM:Infinity,houseFootClearM:Infinity,oreFootClearM:Infinity,ruleTreeFootClearM:Infinity,treeCentreM:Infinity,poissonRatio:Infinity,tallRoadCentreM:Infinity};
 const count:Record<string,number>={};const examples:any[]=[];
 const mark=(kind:string,p:SceneryItem)=>{violations[kind]++;if(examples.length<16)examples.push({kind,sprite:p.sprite,x:p.x,z:p.z,r:p.r});};
 const clearance=(kind:string,v:number,p:SceneryItem)=>{minima[kind+'FootClearM']=Math.min(minima[kind+'FootClearM'],v);if(v < -1e-9)mark(kind==='ruleTree'?'ruleTreeFoot':kind,p);};
 const fixed=items.filter(p=>!p.clearOnBuild),ordinary=items.filter(p=>!p.cross&&p.row<0),byType=new Map<string,SceneryItem[]>();
 let fieldLarge=0,tall=0,forestMin=Infinity,forestMax=-Infinity;
 for(const p of items) {
  count[`${p.zone}.${p.kind}`]=(count[`${p.zone}.${p.kind}`]??0)+1;
  const list=byType.get(p.type)??[];list.push(p);byType.set(p.type,list);
  const road=roadMetrics(p);minima.roadFootClearM=Math.min(minima.roadFootClearM,road.clearance);if(road.clearance < -1e-9)mark('road',p);
  for(const d of base.dressing)clearance('dressing',dist(d,p)-d.r-p.r,p);
  for(const b of map.bridges)clearance('bridge',rectGap(b,p.x,p.z)-p.r,p);
  const keepD=Math.hypot(p.x-map.keep[0],p.z-map.keep[1]);clearance('keepYard',keepD-8.5-p.r,p);
  for(const h of houses)clearance('house',dist(h,p)-h.r-1-p.r,p);
  for(const n of map.nodes)clearance('ore',dist(n,p)-Math.max(3.7,2.2+.5*n.richness+1.5)-p.r,p);
  for(const [x,z] of map.trees){const d=Math.hypot(x-p.x,z-p.z);clearance('ruleTree',d-1.5-p.r,p);if(['tree','bamboo','canopy'].includes(p.kind))minima.treeCentreM=Math.min(minima.treeCentreM,d);}
  if(Math.max(Math.abs(p.x),Math.abs(p.z))+p.r>88+1e-9)mark('bounds',p);
  if(!p.cross&&keepD<=11)mark('keepLarge',p);
  if(!p.cross&&Math.abs(p.x-map.gate[0])<=6&&p.z<=-46)mark('gateLarge',p);
  const wet=water.find(q=>contains(q,p.x,p.z));
  if(wet){const bank=Math.min(p.x-wet.x0,wet.x1-p.x);if((p.type!=='reed-clump'&&p.kind!=='rock')||bank>.6+1e-9||p.x-p.r<wet.x0||p.x+p.r>wet.x1||p.z-p.r<wet.z0||p.z+p.r>wet.z1)mark('water',p);}
  else if(water.some(q=>rectGap(q,p.x,p.z)<p.r-1e-9))mark('water',p);
  if(p.kind!=='rock') {
   let rise4=0,rise64=0;
   for(let k=0;k<64;k++){const a=k*Math.PI/64,dx=Math.cos(a),dz=Math.sin(a);const rise=Math.abs(heightAt(map,p.x-dx,p.z-dz)-heightAt(map,p.x+dx,p.z+dz));rise64=Math.max(rise64,rise);if(k%16===0)rise4=Math.max(rise4,rise);}
   if(rise4>1.4+1e-9)mark('slope4',p);if(rise64>1.4+1e-9)mark('slope64Diagnostic',p);
  }
  if(!p.clearOnBuild) {
   const outsideSquare=Math.hypot(Math.max(Math.abs(p.x)-46,0),Math.max(Math.abs(p.z)-46,0))>=p.r-1e-9;
   const inWater=water.some(q=>p.x-p.r>=q.x0&&p.x+p.r<=q.x1&&p.z-p.r>=q.z0&&p.z+p.r<=q.z1);
   const inKeep=keepD+p.r<=11+1e-9;
   if(!outsideSquare&&!inWater&&!inKeep)mark('fixedBuildableFoot',p);
   if(!outsideSquare)for(let k=-1;k<96;k++){const a=k*Math.PI/48,x=k<0?p.x:p.x+p.r*Math.cos(a),z=k<0?p.z:p.z+p.r*Math.sin(a);if(pointBuildable(x,z)){mark('fixedBuildableProbe',p);break;}}
  }
  if(p.zone==='field'&&!p.clearOnBuild)mark('fieldFixed',p);
  if(p.row<0&&(p.scale<.85||p.scale>1.15))mark('scale',p);
  if(p.tint<.96||p.tint>1.04)mark('tint',p);
  if(p.row>=0){if(p.zone!=='ring')mark('forestZone',p);if(Math.abs(p.shade-Math.pow(.92,p.row))>.001)mark('forestShade',p);if(p.row===0){const d=Math.hypot(Math.max(Math.abs(p.x)-48,0),Math.max(Math.abs(p.z)-48,0));forestMin=Math.min(forestMin,d);forestMax=Math.max(forestMax,d);}}
  if(p.zone==='field'&&!p.cross){fieldLarge++;if(set.find(s=>s.id===p.sprite).heightM>=8){tall++;minima.tallRoadCentreM=Math.min(minima.tallRoadCentreM,road.centre);}}
 }
 let sameSpriteTouching=0;const flipRatios:any={};
 for(const [type,ps] of byType){const variants=new Set(set.filter(s=>s.type===type).map(s=>s.variant));flipRatios[type]={count:ps.length,ratio:ps.filter(p=>p.flip).length/ps.length};
  for(const p of ps){let nearest:SceneryItem|undefined,best=Infinity;for(const q of ps)if(q!==p){const d=square(q.x-p.x)+square(q.z-p.z);if(d<best||(d===best&&nearest&&(q.x<nearest.x||(q.x===nearest.x&&q.z<nearest.z)))){nearest=q;best=d;}}if(variants.size>=2&&nearest?.variant===p.variant)mark('sameNearestVariant',p);}
  for(let a=0;a<ps.length;a++)for(let b=a+1;b<ps.length;b++){const p=ps[a]!,q=ps[b]!;if(!p.cross&&p.sprite===q.sprite&&dist(p,q)<p.r+q.r)sameSpriteTouching++;}
 }
 for(let a=0;a<ordinary.length;a++)for(let b=a+1;b<ordinary.length;b++)minima.poissonRatio=Math.min(minima.poissonRatio,dist(ordinary[a]!,ordinary[b]!)/(ordinary[a]!.r+ordinary[b]!.r));
 let simPoints=0,simAccepted=0;for(const c of cells)if(fixed.some(p=>dist(p,c)<2+p.r)){simPoints++;if(c.ok)simAccepted++;}
 const bin=new Array(144).fill(0);for(const p of ordinary.filter(p=>p.zone==='field'))bin[Math.min(11,Math.floor((p.z+48)/8))*12+Math.min(11,Math.floor((p.x+48)/8))]++;
 const mean=bin.reduce((a,b)=>a+b,0)/144,vmr=mean?bin.reduce((a,b)=>a+square(b-mean),0)/144/mean:0;
 const rows=[0,1,2,3].map(row=>items.filter(p=>p.row===row));const means=rows.map(ps=>ps.reduce((s,p)=>s+p.scale,0)/ps.length);
 return {count,large:items.filter(p=>!p.cross).length,cross:items.filter(p=>p.cross).length,fixed:fixed.length,violations,minima,simPoints,simAccepted,sameSpriteTouching,flipRatios,vmr,fieldTall:{tall,fieldLarge,ratio:fieldLarge?tall/fieldLarge:0},forest:{rowsPerEdge:[0,1,2,3].map(edge=>new Set(items.filter(p=>p.edge===edge&&p.row>=0).map(p=>p.row)).size),frontMin:forestMin,frontMax:forestMax,meanScale:means,growth:means.slice(1).map((v,k)=>v/means[k]!)},examples};
}

const rows:any[]=[];const failures:any[]=[];
for(const [name,set] of [['all26',real],['accepted8',real.filter((s:any)=>s.accepted)]] as const)for(const seed of seeds) {
 const layouts=tiers.map(t=>sceneryLayout({...base,set,seed},t));
 for(let k=0;k<tiers.length;k++) {
  const l=layouts[k]!,r=inspect(l.items,set);
  const higher=k<2?new Set(layouts[k+1]!.items.map(p=>JSON.stringify(p))):undefined;
  const nested=higher?l.items.every(p=>higher.has(JSON.stringify(p))):true;
  const budgets={low:[600,0],medium:[1000,1600],high:[1500,4000]}[l.tier]!;
  const violations=Object.entries(r.violations).filter(([key,n])=>key!=='slope64Diagnostic'&&n>0);
  if(violations.length||r.simAccepted||!nested||r.large>budgets[0]!||r.cross>budgets[1]!||r.minima.treeCentreM<4-1e-9||r.minima.poissonRatio<.8-1e-9)failures.push({name,seed:seed??'default',tier:l.tier,violations,simAccepted:r.simAccepted,nested});
  rows.push({name,seed:seed??'default',resolvedSeed:l.seed,tier:l.tier,nested,sha256:sha(JSON.stringify(l.items)),...r});
 }
 console.log(name,seed??'default','done',rows.at(-1).large,rows.at(-1).cross);
}
const source=readFileSync(new URL('./mutation-tree/src/view/3d/scenery-layout.ts',import.meta.url),'utf8');
const result={scope:'Phiếu 231 · oracle hình học độc lập cho phiếu 202',sourceSha256:sha(source),seeds:seeds.map(s=>s??'default'),layouts:rows.length,sets:{all:real.length,accepted:real.filter((s:any)=>s.accepted).length},oracleIndependence:'Không import inspectLayout / SCENERY_TUNING / FOOT / helper placement. Chỉ lấy lane, width, dressing, height thật; mọi phép hình học tự viết. canPlace chạy độc lập trên 8649 ô 1m, có đủ preset.',towerGrid:{tested:cells.length,legal:cells.filter(p=>p.ok).length,control35_15:cells.find(p=>p.x===35&&p.z===15)?.ok,exportedBuildabilityDisagreements},goldenExpected:JSON.parse(readFileSync(new URL('./mutation-tree/tests/golden/td-scenery-layout.json',import.meta.url),'utf8')),goldenActual:golden,fullByteHashes,failures,rows};
writeFileSync(new URL('./oracle-result.json',import.meta.url),JSON.stringify(result,null,2)+'\n');
console.log('DONE',rows.length,'layouts; failures',failures.length,'dense slope diagnostics',rows.reduce((n,r)=>n+r.violations.slope64Diagnostic,0));
